#!/bin/sh
# Print the three most frequent IP addresses from access.log,
# breaking ties by first appearance in the log.
set -eu
cd "$(dirname "$0")"

awk '
{
    ip = $1
    if (!(ip in first)) {
        first[ip] = NR
    }
    count[ip]++
}
END {
    for (ip in count) {
        print count[ip], first[ip], ip
    }
}
' access.log |
sort -k1,1nr -k2,2n |
head -n 3 |
awk '{ print $3 }'
